            ["studio.targetInfo"] = new[] { "Antes de cada clique, o V-Clicker procura o alvo na janela e só clica se encontrar exatamente um, parado, habilitado e visível. Se não encontrar no tempo máximo, a macro para e explica; o ponto gravado ({0}, {1}) não é usado.", "Before every click, the V-Clicker looks for the target in the window and only clicks if it finds exactly one, still, enabled and visible. If it is not found within the time limit, the macro stops and says why; the recorded point ({0}, {1}) is not used." },
            ["studio.targetImageInfo"] = new[] { "Antes de cada clique, o V-Clicker procura esta imagem na janela e só clica se ela aparecer exatamente uma vez, parada. A aparência precisa continuar a mesma (mesmo zoom do navegador e escala da tela). Se não encontrar no tempo máximo, a macro para e explica; o ponto gravado ({0}, {1}) não é usado.", "Before every click, the V-Clicker looks for this image in the window and only clicks if it shows up exactly once, still. It must keep looking the same (same browser zoom and screen scale). If it is not found within the time limit, the macro stops and says why; the recorded point ({0}, {1}) is not used." },
